script:
frappe.ui.form.on('Item', {
    setup: function(frm) {
        // This ensures the mandatory check is bypassed even inside the Quick Entry popup dialog
        frm.toggle_reqd('item_code', false);
    },
    refresh: function(frm) {
        // Bypass mandatory check on form load if it's a new record
        if (frm.is_new()) {
            frm.toggle_reqd('item_code', false);
        } else {
            // Force display the field if the item is already saved
            frm.toggle_display('item_code', true);
        }

        // Keep the field permanently read-only so users cannot manually edit it
        frm.set_df_property('item_code', 'read_only', 1);
    },
    validate: function(frm) {
        let primary_selected = false;

        // Final sanity check before saving using the table field name
        if (frm.doc.custom_item_domains) {
            frm.doc.custom_item_domains.forEach(row => {
                if (row.primary_domain) {
                    primary_selected = true;
                }
            });
        }

        // Alert the user if they try to save without selecting a primary domain
        if (!primary_selected && frm.is_new()) {
            frappe.msgprint(__('Please check at least one Primary Domain in the Item Domains table.'));
            frappe.validated = false;
        }
    }
});

// REAL-TIME CHILD TABLE TRIGGER
// Using 'Item Domain Detail' because Frappe needs the exact DocType name here
frappe.ui.form.on('Item Domain Detail', {
    primary_domain: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];

        // If user is trying to tick the checkbox
        if (row.primary_domain) {
            let primary_count = 0;

            // Loop through the table field name to count existing active ticks
            if (frm.doc.custom_item_domains) {
                frm.doc.custom_item_domains.forEach(d => {
                    if (d.primary_domain) {
                        primary_count++;
                    }
                });
            }

            // If more than one row is ticked, untick the current row immediately and throw a popup alert
            if (primary_count > 1) {
                frappe.model.set_value(cdt, cdn, 'primary_domain', 0);
                frappe.msgprint(__('You cannot select 2 primary domains. Please untick the previous one first.'));
            }
        }
    }
});
